import { useState } from "react"
//import TodoList from "./TodoList";


export default function TodoForm({onTodoAdd}){
    const [todoText, setTodoText] = useState('');
     return<>
    <div>
        <form action='#' method="GET" onSubmit={(e)=>{
            e.preventDefault();
            onTodoAdd(todoText)
            setTodoText('')
        }}>
            <textarea
             value={todoText}
             onChange={(e)=>{
                setTodoText(e.target.value)
             }}
            ></textarea>
            <button>Save</button>
        </form>
        </div>
        </>
}
